import{_ as r,o,c as l,ae as t}from"./chunks/framework.RRduUuAx.js";const q=JSON.parse('{"title":"자주 묻는 질문(FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"v1/ko/faq/index.md","filePath":"v1/ko/faq/index.md"}'),i={name:"v1/ko/faq/index.md"};function e(n,a,s,h,d,g){return o(),l("div",null,[...a[0]||(a[0]=[t('<h1 id="자주-묻는-질문-faq" tabindex="-1">자주 묻는 질문(FAQ) <a class="header-anchor" href="#자주-묻는-질문-faq" aria-label="Permalink to &quot;자주 묻는 질문(FAQ)&quot;">​</a></h1><p>이 문서는 코알라 가계부 사용 중 자주 발생하는 질문과 해결 방법을 정리했습니다. 문제가 생기면 먼저 여기부터 확인해 보세요.</p><hr><h2 id="내역-가져오기" tabindex="-1">내역 가져오기 <a class="header-anchor" href="#내역-가져오기" aria-label="Permalink to &quot;내역 가져오기&quot;">​</a></h2><h3 id="q-어떤-소스의-내역을-가져올-수-있나요-지원-파일-형식은-무엇인가요" tabindex="-1">Q: 어떤 소스의 내역을 가져올 수 있나요? 지원 파일 형식은 무엇인가요? <a class="header-anchor" href="#q-어떤-소스의-내역을-가져올-수-있나요-지원-파일-형식은-무엇인가요" aria-label="Permalink to &quot;Q: 어떤 소스의 내역을 가져올 수 있나요? 지원 파일 형식은 무엇인가요?&quot;">​</a></h3><p><strong>A:</strong> 현재 5가지 소스를 지원합니다.</p><ul><li><strong>템플릿</strong>: CSV(<code>.csv</code>)</li><li><strong>WeChat</strong>: CSV / Excel(<code>.csv</code> / <code>.xlsx</code> / <code>.xls</code>)</li><li><strong>Alipay</strong>: CSV(<code>.csv</code>)</li><li><strong>Pixiu</strong>: CSV(<code>.csv</code>)</li><li><strong>iCost</strong>: Excel(<code>.xlsx</code> / <code>.xls</code>) — iCost CSV는 지원하지 않습니다</li></ul><p>관련 가이드:</p><ul><li><a href="./../guide/01-template-bill-import-guide">템플릿 내역 가져오기(CSV)</a></li><li><a href="./../guide/02-wechat-bill-import-guide">WeChat 내역 가져오기</a></li><li><a href="./../guide/03-alipay-bill-import-guide">Alipay 내역 가져오기</a></li><li><a href="./../guide/07-pixiu-bill-import-guide">Pixiu 내역 가져오기</a></li><li><a href="./../guide/08-icost-bill-import-guide">iCost 내역 가져오기</a></li></ul><h3 id="q-파싱-실패-열기-실패-헤더를-찾을-수-없음-이-뜹니다" tabindex="-1">Q: “파싱 실패/열기 실패/헤더를 찾을 수 없음”이 뜹니다 <a class="header-anchor" href="#q-파싱-실패-열기-실패-헤더를-찾을-수-없음-이-뜹니다" aria-label="Permalink to &quot;Q: “파싱 실패/열기 실패/헤더를 찾을 수 없음”이 뜹니다&quot;">​</a></h3><p><strong>A:</strong> 대부분 아래 원인 중 하나입니다(자주 발생하는 순).</p><ol><li><strong>가져오기 소스를 잘못 선택함</strong>: 예를 들어 WeChat 파일을 템플릿/Alipay로 파싱하면 검증 실패나 필드 어긋남이 발생할 수 있습니다.</li><li><strong>파일을 편집함</strong>: Excel/WPS로 열어 헤더 변경, 열 삭제/추가, 구분자 변경 등을 하면 파싱이 쉽게 실패합니다.</li><li><strong>지원하지 않는 내보내기 형식</strong>: 예를 들어 iCost를 CSV로 내보내거나, Alipay 비표준 형식을 사용하는 경우.</li><li><strong>파일 손상/불완전</strong>: 다운로드 중단, 첨부 손상, 공유 과정에서 내용 누락 등.</li><li><strong>파일이 너무 큼</strong>: 파일이 크면 느리거나 실패할 수 있습니다. 기간을 나눠 내보낸 뒤 분할 가져오기를 권장합니다.</li></ol><p>권장 방법: 원래 앱에서 “편집하지 않은” 파일을 다시 내보내고, 코알라 가계부에서 가져오기 소스를 정확히 선택한 뒤 다시 파싱하세요.</p><h3 id="q-가져온-금액이-0이-되거나-금액이-맞지-않습니다" tabindex="-1">Q: 가져온 금액이 0이 되거나 금액이 맞지 않습니다 <a class="header-anchor" href="#q-가져온-금액이-0이-되거나-금액이-맞지-않습니다" aria-label="Permalink to &quot;Q: 가져온 금액이 0이 되거나 금액이 맞지 않습니다&quot;">​</a></h3><p><strong>A:</strong> 흔한 원인은 다음과 같습니다.</p><ul><li><strong>수입/지출 판정이 잘못됨</strong>: 일부 소스는 “收入/支出” 같은 키워드로 어떤 금액 열을 읽을지 결정합니다(예: Pixiu 유입/유출). 유형 열이 비정상이면 잘못 읽을 수 있습니다.</li><li><strong>금액 열이 비어 있거나 예상치 못한 문자가 섞임</strong>: 공백/보이지 않는 문자가 원인이 될 수 있습니다.</li><li><strong>천 단위 구분자/부호</strong>: <code>+/-</code> 또는 천 단위 쉼표가 포함될 수 있으며 보통 처리되지만, 편집·재저장 과정에서 형식이 깨지면 실패할 수 있습니다.</li></ul><p>권장: 미리보기에서 <strong>수입/지출 유형</strong>과 <strong>금액</strong>을 먼저 확인하세요. 이상하면 원본 파일을 재내보내는 것이 가장 확실합니다.</p><h3 id="q-카테고리-계정-태그가-원하는-대로-매칭되지-않습니다" tabindex="-1">Q: 카테고리/계정/태그가 원하는 대로 매칭되지 않습니다 <a class="header-anchor" href="#q-카테고리-계정-태그가-원하는-대로-매칭되지-않습니다" aria-label="Permalink to &quot;Q: 카테고리/계정/태그가 원하는 대로 매칭되지 않습니다&quot;">​</a></h3><p><strong>A:</strong> 코알라 가계부가 자동 매칭을 시도하지만, 앱마다 분류 체계가 달라 100% 정확하진 않을 수 있습니다.</p><ul><li><strong>카테고리</strong>: 미리보기에서 단건으로 수정할 수 있습니다. 더 잘 맞추려면 코알라 가계부에 내보내기 파일과 같은 이름의 카테고리를 미리 만들어 둔 뒤 다시 파싱해 보세요.</li><li><strong>계정</strong>: 보통 계정명/결제수단으로 매칭합니다. 없으면 새 계정을 만들 수 있습니다. 자주 쓰는 계정을 미리 만들어 두고, 필요하면 미리보기에서 일괄 수정하세요.</li><li><strong>태그</strong>: 태그명으로 매칭하며, 없는 태그는 생성될 수 있습니다. 불필요한 태그명(공백/기호 포함)이 생기지 않았는지 확인하세요.</li></ul><h3 id="q-중복-가져오기를-자동으로-막아주나요-같은-파일을-두-번-가져오면-어떻게-되나요" tabindex="-1">Q: 중복 가져오기를 자동으로 막아주나요? 같은 파일을 두 번 가져오면 어떻게 되나요? <a class="header-anchor" href="#q-중복-가져오기를-자동으로-막아주나요-같은-파일을-두-번-가져오면-어떻게-되나요" aria-label="Permalink to &quot;Q: 중복 가져오기를 자동으로 막아주나요? 같은 파일을 두 번 가져오면 어떻게 되나요?&quot;">​</a></h3><p><strong>A:</strong> 소스에 따라 다르지만, 안전하게는 <strong>자동 중복 제거가 없다고 생각하고</strong> 사용하시는 것이 좋습니다.</p><ul><li>권장: 같은 파일/같은 기간을 반복해서 가져오지 마세요. 분할 가져오기라면 기간이 겹치지 않게 하세요.</li><li>이미 중복이 생겼다면: 내역 목록에서 기간을 좁혀 수동으로 삭제해 주세요.</li></ul><h3 id="q-환불-이체-红包-같은-특수-거래는-어떻게-되나요" tabindex="-1">Q: 환불/이체/红包 같은 특수 거래는 어떻게 되나요? <a class="header-anchor" href="#q-환불-이체-红包-같은-특수-거래는-어떻게-되나요" aria-label="Permalink to &quot;Q: 환불/이체/红包 같은 특수 거래는 어떻게 되나요?&quot;">​</a></h3><p><strong>A:</strong> 플랫폼마다 내보내기 구조가 달라서, 가져온 뒤에는 다음을 권장합니다.</p><ul><li>미리보기에서 <strong>수입/지출 유형</strong>과 <strong>금액 부호</strong>를 확인</li><li>필요하면 카테고리를 수동 조정(예: 환불을 “환불/기타 수입” 등으로)</li><li>거래 상태/주문번호 등은 메모에 합쳐 저장되는 경우가 많아 추적에 도움이 됩니다</li></ul><h3 id="q-한-번에-얼마나-가져오는-게-좋나요-가져오기가-느립니다" tabindex="-1">Q: 한 번에 얼마나 가져오는 게 좋나요? 가져오기가 느립니다 <a class="header-anchor" href="#q-한-번에-얼마나-가져오는-게-좋나요-가져오기가-느립니다" aria-label="Permalink to &quot;Q: 한 번에 얼마나 가져오는 게 좋나요? 가져오기가 느립니다&quot;">​</a></h3><p><strong>A:</strong> 기간을 나눠 가져오는 것이 좋습니다.</p><ul><li>WeChat/Alipay는 보통 <strong>3개월 이내</strong>로 내보내면 더 안정적이고 빠릅니다</li><li>대량 데이터는 여러 파일로 나눠 하나씩 가져오세요</li><li>가져오기 중에는 앱을 전면에 두는 것을 권장합니다(중단 방지)</li></ul><hr><h2 id="다중-장부" tabindex="-1">다중 장부 <a class="header-anchor" href="#다중-장부" aria-label="Permalink to &quot;다중 장부&quot;">​</a></h2><h3 id="q-장부를-바꿨더니-데이터가-사라진-것처럼-보여요" tabindex="-1">Q: 장부를 바꿨더니 데이터가 “사라진” 것처럼 보여요 <a class="header-anchor" href="#q-장부를-바꿨더니-데이터가-사라진-것처럼-보여요" aria-label="Permalink to &quot;Q: 장부를 바꿨더니 데이터가 “사라진” 것처럼 보여요&quot;">​</a></h3><p><strong>A:</strong> 다른 장부로 전환되었을 가능성이 큽니다. 내역·카테고리·태그·통계는 장부별로 분리됩니다.</p><p>권장: <strong>장부 관리</strong>에서 현재 장부를 확인한 뒤 내역 목록을 다시 확인해 주세요.</p><h3 id="q-장부별로-분리되는-것과-공유되는-것은-무엇인가요" tabindex="-1">Q: 장부별로 분리되는 것과 공유되는 것은 무엇인가요? <a class="header-anchor" href="#q-장부별로-분리되는-것과-공유되는-것은-무엇인가요" aria-label="Permalink to &quot;Q: 장부별로 분리되는 것과 공유되는 것은 무엇인가요?&quot;">​</a></h3><p><strong>A:</strong></p><ul><li><strong>장부별</strong>: 내역, 카테고리, 태그, 통계</li><li><strong>기기 공유</strong>: 계정(Accounts) — 여러 장부에서 같은 계정을 사용할 수 있습니다</li></ul><h3 id="q-장부를-삭제하면-어떻게-되나요-복구할-수-있나요" tabindex="-1">Q: 장부를 삭제하면 어떻게 되나요? 복구할 수 있나요? <a class="header-anchor" href="#q-장부를-삭제하면-어떻게-되나요-복구할-수-있나요" aria-label="Permalink to &quot;Q: 장부를 삭제하면 어떻게 되나요? 복구할 수 있나요?&quot;">​</a></h3><p><strong>A:</strong> 장부를 삭제하면 해당 장부 데이터가 이 기기에서 제거됩니다. 클라우드 동기화를 사용 중이라면, 다음 동기화 때 클라우드에도 삭제가 반영됩니다. 앱 안에서 복구할 수 없으니 삭제 전 꼭 확인해 주세요.</p><hr><h2 id="통화-및-환율" tabindex="-1">통화 및 환율 <a class="header-anchor" href="#통화-및-환율" aria-label="Permalink to &quot;통화 및 환율&quot;">​</a></h2><h3 id="q-기준-통화-장부-통화가-무엇인가요-어디에-영향을-주나요" tabindex="-1">Q: 기준 통화/장부 통화가 무엇인가요? 어디에 영향을 주나요? <a class="header-anchor" href="#q-기준-통화-장부-통화가-무엇인가요-어디에-영향을-주나요" aria-label="Permalink to &quot;Q: 기준 통화/장부 통화가 무엇인가요? 어디에 영향을 주나요?&quot;">​</a></h3><p><strong>A:</strong> 기준 통화(장부 통화)는 현재 장부에서 “주로 표시하는 통화”입니다. 다음에 영향을 줍니다.</p><ul><li>금액 표시(환산 표시)</li><li>개요/통계 계산 기준</li><li>환율 목록(기준 통화 대비 환율 표시)</li></ul><h3 id="q-환율을-새로-고친-뒤-과거-내역의-환산-표시가-바뀌었어요" tabindex="-1">Q: 환율을 새로 고친 뒤, 과거 내역의 환산 표시가 바뀌었어요 <a class="header-anchor" href="#q-환율을-새로-고친-뒤-과거-내역의-환산-표시가-바뀌었어요" aria-label="Permalink to &quot;Q: 환율을 새로 고친 뒤, 과거 내역의 환산 표시가 바뀌었어요&quot;">​</a></h3><p><strong>A:</strong> 코알라 가계부는 <strong>현재 환율</strong>을 사용해 환산 표시를 합니다. 환율을 새로 고치거나 기준 통화를 바꾸면 과거 내역의 <strong>환산 표시</strong>가 달라질 수 있지만, <strong>원거래 금액</strong>은 바뀌지 않습니다.</p><h3 id="q-오프라인일-때는-어떻게-되나요-새로고침이-실패해요" tabindex="-1">Q: 오프라인일 때는 어떻게 되나요? 새로고침이 실패해요 <a class="header-anchor" href="#q-오프라인일-때는-어떻게-되나요-새로고침이-실패해요" aria-label="Permalink to &quot;Q: 오프라인일 때는 어떻게 되나요? 새로고침이 실패해요&quot;">​</a></h3><p><strong>A:</strong> 오프라인일 때는 저장된 환율을 최대한 사용합니다. 새로고침이 실패하면:</p><ol><li>네트워크 상태를 확인</li><li>잠시 후 다시 시도</li><li>수동으로 환율을 수정했다면 값이 의도한 대로인지 확인</li></ol><hr><h2 id="클라우드-백업-및-동기화" tabindex="-1">클라우드 백업 및 동기화 <a class="header-anchor" href="#클라우드-백업-및-동기화" aria-label="Permalink to &quot;클라우드 백업 및 동기화&quot;">​</a></h2><h3 id="q-클라우드-백업을-쓰려면-로그인해야-하나요-어떤-로그인-방식을-지원하나요" tabindex="-1">Q: 클라우드 백업을 쓰려면 로그인해야 하나요? 어떤 로그인 방식을 지원하나요? <a class="header-anchor" href="#q-클라우드-백업을-쓰려면-로그인해야-하나요-어떤-로그인-방식을-지원하나요" aria-label="Permalink to &quot;Q: 클라우드 백업을 쓰려면 로그인해야 하나요? 어떤 로그인 방식을 지원하나요?&quot;">​</a></h3><p><strong>A:</strong> 네. 현재는 <strong>Apple 로그인</strong>을 지원합니다. 설정 화면 상단의 사용자 카드에서 로그인할 수 있습니다.</p><h3 id="q-무엇이-동기화되고-무엇이-동기화되지-않나요" tabindex="-1">Q: 무엇이 동기화되고, 무엇이 동기화되지 않나요? <a class="header-anchor" href="#q-무엇이-동기화되고-무엇이-동기화되지-않나요" aria-label="Permalink to &quot;Q: 무엇이 동기화되고, 무엇이 동기화되지 않나요?&quot;">​</a></h3><p><strong>A:</strong></p><ul><li><strong>동기화됨</strong>: 장부, 내역, 계정, 카테고리, 태그</li><li><strong>동기화되지 않음</strong>: 앱 설정(테마/언어), 캐시, 개인 설정</li></ul><h3 id="q-자동-동기화는-언제-되나요-수동-동기화는-어떻게-하나요" tabindex="-1">Q: 자동 동기화는 언제 되나요? 수동 동기화는 어떻게 하나요? <a class="header-anchor" href="#q-자동-동기화는-언제-되나요-수동-동기화는-어떻게-하나요" aria-label="Permalink to &quot;Q: 자동 동기화는 언제 되나요? 수동 동기화는 어떻게 하나요?&quot;">​</a></h3><p><strong>A:</strong></p><ul><li><strong>자동</strong>: 앱 실행 시, 데이터 변경 후, 장부 전환 시 등</li><li><strong>수동</strong>: 설정 화면 우측 상단의 구름 아이콘을 탭</li></ul><p>수동 동기화 중에는 완료될 때까지 앱을 전면에 두는 것을 권장합니다.</p><h3 id="q-여러-기기에서-같은-데이터를-동시에-수정하면-어떻게-되나요" tabindex="-1">Q: 여러 기기에서 같은 데이터를 동시에 수정하면 어떻게 되나요? <a class="header-anchor" href="#q-여러-기기에서-같은-데이터를-동시에-수정하면-어떻게-되나요" aria-label="Permalink to &quot;Q: 여러 기기에서 같은 데이터를 동시에 수정하면 어떻게 되나요?&quot;">​</a></h3><p><strong>A:</strong> 코알라 가계부는 가능한 한 최신 변경을 유지하면서, 아직 업로드되지 않은 로컬 변경이 덮어쓰여지지 않도록 처리합니다. 여러 기기를 함께 쓸 때는 한 기기에서 동기화를 완료한 뒤 다른 기기에서 편집하는 것이 좋습니다.</p><h3 id="q-재설치-기기-변경-후에-복구할-수-있나요" tabindex="-1">Q: 재설치/기기 변경 후에 복구할 수 있나요? <a class="header-anchor" href="#q-재설치-기기-변경-후에-복구할-수-있나요" aria-label="Permalink to &quot;Q: 재설치/기기 변경 후에 복구할 수 있나요?&quot;">​</a></h3><p><strong>A:</strong></p><ul><li><strong>로그인 및 동기화 완료</strong>: 재설치 후 같은 계정으로 로그인하고 동기화가 끝나면 복구됩니다</li><li><strong>미로그인</strong>: 데이터가 기기에만 있으므로 삭제/재설치 시 복구할 수 없습니다</li></ul><hr><h2 id="멤버십-및-요금" tabindex="-1">멤버십 및 요금 <a class="header-anchor" href="#멤버십-및-요금" aria-label="Permalink to &quot;멤버십 및 요금&quot;">​</a></h2><h3 id="q-왜-멤버십을-한-번에-구매하는-영구-방식으로-제공하지-않나요" tabindex="-1">Q: 왜 멤버십을 한 번에 구매하는(영구) 방식으로 제공하지 않나요? <a class="header-anchor" href="#q-왜-멤버십을-한-번에-구매하는-영구-방식으로-제공하지-않나요" aria-label="Permalink to &quot;Q: 왜 멤버십을 한 번에 구매하는(영구) 방식으로 제공하지 않나요?&quot;">​</a></h3><p><strong>A:</strong> 코알라 가계부를 “한 번 팔고 끝”이 아니라, 장기적으로 계속 개선해 나가는 제품으로 만들고 싶기 때문입니다.</p><p>멤버십 모델은 지속 가능한 개발에 도움이 됩니다. 버그 수정과 사용성 개선을 꾸준히 이어가고, OS 업데이트/신규 기기에도 계속 대응할 수 있습니다. 또한 동기화, 데이터 안전, 성능처럼 장기적인 투자가 필요한 영역도 꾸준히 강화할 수 있어, 구매 후 업데이트가 느려지거나 유지보수가 어려워지는 위험을 줄일 수 있습니다.</p><hr><h2 id="문의-및-지원" tabindex="-1">문의 및 지원 <a class="header-anchor" href="#문의-및-지원" aria-label="Permalink to &quot;문의 및 지원&quot;">​</a></h2><h3 id="q-문제를-제보할-때-무엇을-함께-보내면-좋나요" tabindex="-1">Q: 문제를 제보할 때 무엇을 함께 보내면 좋나요? <a class="header-anchor" href="#q-문제를-제보할-때-무엇을-함께-보내면-좋나요" aria-label="Permalink to &quot;Q: 문제를 제보할 때 무엇을 함께 보내면 좋나요?&quot;">​</a></h3><p><strong>A:</strong> 정보가 많을수록 원인 파악이 빠릅니다. 아래를 권장합니다.</p><ul><li>가져오기 소스(WeChat/Alipay/Pixiu/iCost/템플릿)</li><li>파일 형식(CSV/Excel)과 내보낸 기간</li><li>오류 메시지 스크린샷(있다면)</li><li>이미 시도해 본 것(재내보내기, 소스 변경, 다른 파일로 테스트 등)</li></ul>',75)])])}const c=r(i,[["render",e]]);export{q as __pageData,c as default};
